function LiveChatAvAcceptInterfaceImpl(avi, sid, uid, mode, callId, conference, offering) {
    var this_ = this;

    // call base constructor
    LiveChatAvAcceptInterface(this_);

    this_.avi_ = avi;
    this_.sid_ = sid;
    this_.uid_ = uid;
    this_.mode_ = "";
    this_.receiving_ = offering;
    this_.completed_ = false;
    this_.callId_ = callId;
    this_.conference_ = conference;
    this_.downgrade_ = false;
    this_.utils_ = new LiveChatAvUtilitiesInterfaceImpl();

    this_.type = function () {
        return this_.mode_;
    }

    this_.offering = function () {
        return this_.receiving_;
    }

    this_.callId = function () {
        return this_.callId_;
    }

    this_.downgrade = function () {
        if (!this_.completed_ && this_.mode_ == LiveChatAvCallTypes.VIDEO && !this_.conference_) {
            this_.downgrade_ = true;
        }
    }

    this_.accept = function (config) {
        var ret = false;

        if (!this_.completed_) {
            this_.completed_ = true;

            var type = undefined;
            if (config != null && typeof config === 'object') {
                type = config.call;
            } else {
                type = config;
                config = undefined;
            }

            var avmode = (this_.mode_ == LiveChatAvCallTypes.AUDIO ? 1 : 2);
            if (type != null) {
                if (type == LiveChatAvCallTypes.AUDIO && this_.mode_ == LiveChatAvCallTypes.VIDEO && !this_.conference_) {
                    avmode = 1;
                }
            } else if (this_.downgrade_) {
                avmode = 1;
            } else if (this_.mode_ === LiveChatAvCallTypes.SCREENSHARE) {
                avmode = this_.mode_;
            }

            ret = this_.avi_._accept(this_.sid_, this_.uid_, avmode, this_.callId_, this_.conference_, config);
        }

        return ret;
    }

    this_.reject = function () {
        var ret = false;

        if (!this_.completed_) {
            this_.completed_ = true;
            ret = this_.avi_._reject(false, this_.callId_, this_.conference_, this_.mode_ === LiveChatAvCallTypes.SCREENSHARE ? true : false);
        }

        return ret;
    }

    this_.close = function () {
        this_.completed_ = true;
    }

    this_._init = function (mode) {
        this_.mode_ = this_.utils_._getCallType(mode);

        if (this_.callId_ == null) {
            this_.callId_ = this_.utils_._genuuidv4();
        }
    }

    this_._init(mode);
}

