    this_._onStats = function (statsReport) {
        this_._debug('Event _onStats triggered');
        try {
            const report = LiveChatAvAnlazizeRtcStatsImpl(statsReport);
            this_._pushMediaReport(report);
            let strength = report.audio.local.mos;
            if (this_.callType_ !== 1 && report.video.local.mos > 0) {
                strength = (report.audio.local.mos + report.video.local.mos) / 2;
            }
            strength = strength.toFixed(2);
            if (this_.lastMosValue_ !== strength) {
                this_.lastMosValue_ = strength;
                this_._onSignalStrengthChange(strength, this_.callId_);
            }

            this_.__onStats(statsReport, this_.callId_);
        } catch (e) {
            this_._warn('Event triggered a exception in user code (event:_onStats, exception:' + e.message + ')');
        }
    }

    this_._reset = function () {
        if (this_.pc_ != null) {
            this_.pc_.close();
        }

        this_._startStopFlushTimer(false);

        this_.pc_ = undefined;

        this_.awaitingAccept_ = false;
        this_.awaitingIncoming_ = true;

        if (this_.acceptObj_ != null) {
            this_.acceptObj_.close();
            this_.acceptObj_ = null;
        }

        if (this_.acceptTimer_ != null) {
            clearTimeout(this_.acceptTimer_);
            this_.acceptTimer_ = null;
        }

        this_.remoteStreams_ = {};
        this_.remoteStreamsInfo_ = {};
        this_.locaStreams_ = {};
        this_.streamStatusInfo_ = {};
        this_.connectTriggered_ = false;
        this_.acceptRecieved_ = false;
        this_.isOnHold_ = false;
        this_.ongoingCall_ = false;
        this_.callType_ = LiveChatAvCallTypes.AUDIO;
        this_.reportQueue_ = [];
        this_.statsReport_ = {};
        this_.awaitingStatus_ = false;
        this_.meetingCall_ = false;

        this_.callState_ = LiveChatAVConst.CallState.INITIAL;
        this_.remoteIceCount_ = 0;
        this_.localIceCount_ = 0;

        this_._screenshareReset();

        this_.awaitingScreenshareIncoming_ = false;

        try {
            this_.__onRemoveVirtualBackgroundStreams(this_.callId_);
        } catch (e) {
            this_._warn('Event triggered a exception in user code (event:this_._reset - onRemoveVirtualBackgroundStreams, exception:' + e.message + ')');
        }
        this_.callId_ = null;
        this_.lastDeviceChangeEventTime_ =  Date.now();
        
        this_.webPhoneMode_ = false;
        this_.dnis_ = null;
    }

    this_._screenshareReset = function () {
        this_.screenshareStartTriggered_ = false;
        this_.screenshareConnectTriggered_ = false;
        this_.isScreensharePresenter_ = false;
        this_.screensharePresenterId_ = "";
        this_.screenshareStream_ = {};
        this_.screenshareRemoteStream_ = {};
        this_.isScreenshareCall_ = false;
        if (this_.screenshareConnectTriggerTimer_ !== null) {
            clearTimeout(this_.screenshareConnectTriggerTimer_);
            this_.screenshareConnectTriggerTimer_ = null;
        }

        if (this_.acceptObj_ != null) {
            this_.acceptObj_.close();
            this_.acceptObj_ = null;
        }

        if (this_.acceptTimer_ != null) {
            clearTimeout(this_.acceptTimer_);
            this_.acceptTimer_ = null;
        }

        this_.awaitingScreenshareStatus_ = false;

        if (this_.connectTriggered_) {
            this_.awaitingScreenshareIncoming_ = true; //This scenario will happen when there is an ongoing a/v call and screenshare is ended during the call
        }

        this_.muteLocalVideoDuringScreenshare = true; 
        if (this_.screenshareCapture_ != null && typeof this_.screenshareCapture_.then === 'function') {
            //If the promise is still being fullfilled, we wait until its resolved and then reset it
            Promise.resolve(this_.screenshareCapture_).then(function (stream) {
                stream.getTracks().forEach(function (track) {
                    track.stop();
                });
                this_.screenshareCapture_ = {};
            });
        }
        else {
            this_.screenshareCapture_ = {};
        }
    }

    this_._updateCallbacks = function (config) {
        this_._cloneConfig(config);
    }

    this_._start = function () {
        this_.remoteStreams_ = {};
        this_.remoteStreamsInfo_ = {};
        this_.locaStreams_ = {};
        this_.connectTriggered_ = false;

        this_.pc_.call();
    }

    this_._end = function (triggerDisconnect, errorCode = "NORMAL_CALL_DISCONNECT") {
        this_.remoteStreams_ = {};
        this_.remoteStreamsInfo_ = {};
        this_.locaStreams_ = {};

        if (this_.pc_ != null) {
            this_.pc_.close();
        }

        if (!triggerDisconnect)
            this_.connectTriggered_ = false;

        this_._pcOnDisconnectImpl(errorCode);

        this_._startStopFlushTimer(false);
    }

    this_._pause = function (audio, video, screenshareVideo) {
        if (this_.pc_ != null) {
            //First we need to get the current track status (so that we can send signalling messages later)
            var previousTrackStatus = this_.pc_.getMuteUnmuteStatus();
            this_.pc_.mute(audio, video, screenshareVideo);
            this_.pc_.unMute(!audio, !video, !screenshareVideo);
            
            var newTrackStatus = this_.pc_.getMuteUnmuteStatus();

            this_._SendMuteUnmuteToRemoteUsers(newTrackStatus, previousTrackStatus);
        }
    }

    this_._SendMuteUnmuteToRemoteUsers = function (newTrackStatus, previousTrackStatus) {
        //For each mute/unmute, we need to send the both audio and video stream mute to both the user
        //define the avmsg for audio mute by default. param specify the stream type.
        var avmsg = {
            type: LiveChatSignallingMessageTypes.CALL.MUTE, 
            param: "audio", 
            owner: this_._getMyId(), 
            target: "service:MSS", 
            callId: this_.callId_
        };

        //Detect audio mute change from its previous state.
        if (previousTrackStatus.audioEnabled !== newTrackStatus.audioEnabled) {
            avmsg.type = LiveChatSignallingMessageTypes.CALL.MUTE;
            avmsg.param = "audio";

            //check for audio unmute and set the values accordingly
            if (newTrackStatus.audioEnabled) {
                avmsg.type = LiveChatSignallingMessageTypes.CALL.UNMUTE;
            }
            //send the audio mute or unmute message to remote user, no need to explicitly check for audio 
            //mute, as the default avmsg declaration contains audio mute message.
            this_.send(avmsg);
        }

        //detect video mute state change from previous state
        if (previousTrackStatus.videoEnabled !== newTrackStatus.videoEnabled) {
            avmsg.type = LiveChatSignallingMessageTypes.CALL.MUTE;
            avmsg.param = "video";

            //check for video unmute and set the values accordingly
            if (newTrackStatus.videoEnabled) {
                avmsg.type = LiveChatSignallingMessageTypes.CALL.UNMUTE;
            }
            //Send video mute or unmute message to remote user.
            this_.send(avmsg);
        }
        
        if (previousTrackStatus.screenshareEnabled !== newTrackStatus.screenshareEnabled) {
            avmsg.type = LiveChatSignallingMessageTypes.SCREENSHARE.MUTE;
            avmsg.param = "screenshareVideo";

            //check for video unmute and set the values accordingly
            if (newTrackStatus.screenshareEnabled) {
                avmsg.type = LiveChatSignallingMessageTypes.SCREENSHARE.UNMUTE;
            }
            //Send video mute or unmute message to remote user.
            this_.send(avmsg);
        }
    }

    this_._accepted = function (remote) {
        var triggerRinging = (remote && !this_.acceptRecieved_);
        this_.acceptRecieved_ = true;

        if (triggerRinging) {
            this_._onRemoteRinging(this_.uids_[ 0 ]);
        }
    }

