    // WrsConfigurationInterface implementation
    this_.getWebRTCConfigurations = function () {
		if (LivechatAVLibrarySettings.LiveChatAvUseLegacySDP) {
			this_.webRtcConfigs_.sdpSemantics = 'plan-b';
		}
		
        return this_.webRtcConfigs_;
    }

    this_.getMediaConstraints = function () {
        return { custom: true };
    }

    this_.getOfferOptions = function () {
        this_.offerOptions_.offerToReceiveAudio = true;
        // [PQ-784] - Agent stream stuck when customer starts sharing the screen (Since offerToReceiveVideo is false). Offer to receive video should be true if the remote streams has video stream or if customer starts sharing the screen
		this_.offerOptions_.offerToReceiveVideo = (this_.callType_ == LiveChatAvCallTypes.VIDEO) || this_._hasRemoteVideoStreams();
        this_.offerOptions_.iceRestart = true;
        return this_.offerOptions_;
    }

    // [PQ-784] - Agent stream stuck when customer starts sharing the screen (Since offerToReceiveVideo is false)
    // Check if any remote streams have video stream
    this_._hasRemoteVideoStreams = function () {
        return Object.keys(this_.remoteStreams_).some((streamId) => this_.remoteStreams_[streamId].getVideoTracks().length > 0);
    }

    this_.singlePartyMode = function() {
        return (this_.meetingCall_ === true);
    }

